<script setup>
import { computed, onUnmounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, errorMessage } from '../api';
import { cart, cartItems, cartCount, cartPayload, flushCart, money, user, deliveryAreas, isOpen, loadConfiguration } from '../store';
const route=useRoute();const router=useRouter();
const fulfillment=ref(route.query.type === 'pickup' ? 'pickup' : 'delivery');
const area=ref(Number(route.query.area) || deliveryAreas.value[0]?.id || '');
const addresses=ref([]);const savedAddress=ref('');const couponDraft=ref(String(route.query.coupon || ''));const couponCode=ref(couponDraft.value);
const form=reactive({customer_name:user.value?.name || '',customer_email:user.value?.email || '',customer_phone:user.value?.phone || '',address:'',landmark:'',instructions:'',customer_note:''});
const quote=ref(null);const quoteBusy=ref(false);const busy=ref(false);const error=ref('');
const randomBytes=crypto.getRandomValues(new Uint8Array(16));randomBytes[6]=(randomBytes[6]&15)|64;randomBytes[8]=(randomBytes[8]&63)|128;
const hex=Array.from(randomBytes,b=>b.toString(16).padStart(2,'0')).join('');const requestId=`${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`;
const quotePayload=computed(()=>({items:cartPayload(),order_type:fulfillment.value,delivery_area_id:fulfillment.value==='delivery' ? Number(area.value) || null : null,coupon_code:couponCode.value || null}));
let timer;let requestNumber=0;
async function calculate(){const request=++requestNumber;quoteBusy.value=true;error.value='';quote.value=null;try{const payload=JSON.parse(JSON.stringify(quotePayload.value));await loadConfiguration();const result=await api.post('/orders/quote',payload);if(request===requestNumber)quote.value=result.data.data;}catch(failure){if(request===requestNumber)error.value=errorMessage(failure);}finally{if(request===requestNumber)quoteBusy.value=false;}}
watch(quotePayload,()=>{quote.value=null;clearTimeout(timer);timer=setTimeout(calculate,250);},{deep:true,immediate:true});
function selectAddress(){const address=addresses.value.find(item=>item.id===Number(savedAddress.value));if(!address)return;form.address=address.address;form.landmark=address.landmark || '';form.customer_phone=address.phone;const match=deliveryAreas.value.find(item=>item.name.toLowerCase()===address.area.toLowerCase() && item.city.toLowerCase()===address.city.toLowerCase());area.value=match?.id || '';}
api.get('/addresses').then(({data})=>{addresses.value=data.data;const address=addresses.value.find(item=>item.is_default);if(address){savedAddress.value=address.id;selectAddress();}}).catch(failure=>{error.value=errorMessage(failure);});
async function placeOrder(){if(busy.value || !quote.value)return;busy.value=true;error.value='';try{await flushCart();const {data}=await api.post('/orders',{...quotePayload.value,customer_name:form.customer_name,customer_email:form.customer_email,customer_phone:form.customer_phone,delivery_address:fulfillment.value==='delivery' ? {address:form.address,landmark:form.landmark,instructions:form.instructions} : null,customer_note:form.customer_note,payment_method:fulfillment.value==='delivery' ? 'cash_on_delivery' : 'cash_on_pickup',request_id:requestId});cart.value=[];await router.replace({path:`/account/orders/${data.data.id}`,query:{placed:'1'}});}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
onUnmounted(()=>{clearTimeout(timer);requestNumber++;});
</script>
<template><section class="container section-space"><template v-if="cartCount"><div class="page-heading"><div class="eyebrow">ONE LAST LITTLE STEP</div><h1>Let’s make it <span class="serif accent">delicious.</span></h1><p>Freshly prepared, just for you. Pay in cash when your food arrives or at pickup.</p></div><div v-if="!isOpen" class="form-error">Restaurant is currently closed. Please order during opening hours.</div><div v-if="error" class="form-error" role="alert">{{ error }}</div><form @submit.prevent="placeOrder" class="cart-layout"><div class="checkout-form"><h3>How would you like your food?</h3><div class="fulfillment-options"><button type="button" :class="{selected:fulfillment==='delivery'}" @click="fulfillment='delivery'">Home delivery</button><button type="button" :class="{selected:fulfillment==='pickup'}" @click="fulfillment='pickup'">Self pickup · Free</button></div><h3>Your details</h3><div class="form-grid"><label>Full name<input v-model="form.customer_name" required autocomplete="name" maxlength="80"></label><label>Phone number<input v-model="form.customer_phone" type="tel" required pattern="[+0-9 ()-]{7,20}" autocomplete="tel"></label><label class="full-width">Email<input v-model="form.customer_email" type="email" required autocomplete="email"></label><template v-if="fulfillment==='delivery'"><label v-if="addresses.length" class="full-width">Saved address<select v-model="savedAddress" @change="selectAddress"><option value="">Enter a new address</option><option v-for="address in addresses" :key="address.id" :value="address.id">{{ address.label }} · {{ address.area }}, {{ address.city }}</option></select></label><label class="full-width">Delivery area & city<select v-model="area" required><option value="" disabled>Choose a supported delivery area</option><option v-for="item in deliveryAreas" :key="item.id" :value="item.id">{{ item.name }}, {{ item.city }} · {{ money(item.fee) }}</option></select></label><label class="full-width">Street address<textarea v-model="form.address" required autocomplete="street-address" placeholder="House, street and building" maxlength="500"></textarea></label><label class="full-width">Landmark <span>(optional)</span><input v-model="form.landmark" maxlength="150"></label><label class="full-width">Delivery instructions <span>(optional)</span><textarea v-model="form.instructions" maxlength="500"></textarea></label></template><label class="full-width">Kitchen notes <span>(optional)</span><textarea v-model="form.customer_note" placeholder="Special requests or allergy information" maxlength="1000"></textarea></label><label class="full-width">Payment method<select :value="fulfillment==='delivery' ? 'cash_on_delivery' : 'cash_on_pickup'"><option :value="fulfillment==='delivery' ? 'cash_on_delivery' : 'cash_on_pickup'">{{ fulfillment==='delivery' ? 'Cash on delivery' : 'Cash on pickup' }}</option></select></label></div><div class="payment-note"><strong>Secure ordering. No online payment required.</strong><p>Your order is saved with the restaurant when you confirm.</p></div></div><aside class="order-summary"><h3>Your order</h3><div v-for="item in cartItems" :key="item.key"><span>{{ item.quantity }} × {{ item.name }}<small class="cart-customization"> {{ item.customization }}</small></span><strong>{{ money(item.quantity*item.price) }}</strong></div><div class="coupon-form"><label>Coupon code<input v-model="couponDraft" maxlength="50" placeholder="WELCOME20"></label><button type="button" @click="couponCode=couponDraft.trim().toUpperCase();calculate()" :disabled="busy || quoteBusy">Apply</button></div><button v-if="couponCode" type="button" class="text-button" @click="couponCode='';couponDraft=''">Remove coupon</button><template v-if="quote"><div><span>Subtotal</span><strong>{{ money(quote.subtotal) }}</strong></div><div><span>Discount</span><strong>− {{ money(quote.discount) }}</strong></div><div><span>Delivery</span><strong>{{ money(quote.delivery_fee) }}</strong></div><div><span>Tax</span><strong>{{ money(quote.tax) }}</strong></div><div class="summary-total"><span>Total</span><strong>{{ money(quote.total) }}</strong></div></template><p v-else>{{ quoteBusy ? 'Checking your order…' : 'Resolve the message above to continue.' }}</p><button class="button" type="submit" :disabled="busy || quoteBusy || !quote || !isOpen">{{ busy ? 'Placing your order…' : 'Confirm order' }} →</button><p>Prices and availability are validated by the restaurant.</p><router-link to="/cart" class="text-button">← Edit your bag</router-link></aside></form></template><div v-else class="empty-state"><h2>Your bag is empty</h2><p>Add something delicious before checking out.</p><router-link class="button" to="/menu">Explore the menu ↗</router-link></div></section></template>
